arguments.command:
cd /tmp/scratchpad 2>/dev/null || mkdir -p /tmp/scratchpad && cd /tmp/scratchpad
# Build a chronological list of friend commits with full body
git --git-dir=/home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill/.git log --all --format='COMMIT %H%nTIME %ci%nSUBJECT %s%n' --grep='Friend-Message' | head -5 >/dev/null
# Instead iterate branches
for sha in $(git -C /home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill rev-list --all --grep='Friend-Message' | sort -u); do
  echo "===== $sha =====";
  git -C /home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill show -s --format='%ci' $sha;
  git -C /home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill show $sha | sed -n '/^Friend-Message:/,$p' | head -40;
done 2>&1 | head -200
